 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=b.new_page(viewport={'width':1440,'height':1000});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(BASE+'/apps/financial-reset/');page.locator('#demo-scenario').select_option('family');page.locator('#demo').click();page.wait_for_timeout(600);assert page.locator('#reset-plan > .plan-action').count()==3;assert page.locator('#reset-plan > .plan-action[open]').count()==0;assert page.locator('#report-details > details[open]').count()==0;assert page.locator('#next-action').is_visible();assert page.locator('#report .guidance-grid').count()==0;before=page.locator('#next-action strong').inner_text();page.locator('#open-next-action').click();opened=page.locator('.plan-action[open]');assert opened.count()==1;opened.locator('[data-key=status]').select_option('done');assert page.locator('#next-action strong').inner_text()!=before
