 info.value.save_as('/tmp/dashboard-full-report.txt');text=open('/tmp/dashboard-full-report.txt').read();assert 'Every expense, four saving pillars' in text;assert 'RRSP deductions alongside CCB' in text;assert 'Annual quote: $300.00' in text;assert page.locator('#report-details > details[open]').count()==0
